def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Rules:
    - `text` is the config contents itself; nothing is read from files.
    - Each line is split at its first "=", so values may contain "=".
    - Whitespace around the name and around the value is stripped.
    - Blank lines, lines starting with "#" (after stripping), and lines
      without "=" are ignored.
    - Key matching is exact and case-sensitive.
    - If the key appears more than once, the first occurrence wins.
    - Returns "" when the key is absent. A key present with nothing after
      the "=" also yields "".
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    text = "host=localhost\nport=8080\nmode=fast"
    assert config_value(text, "host") == "localhost"
    assert config_value(text, "port") == "8080"
    assert config_value(text, "mode") == "fast"


def test_absent_key_returns_empty_string() -> None:
    assert config_value("a=1\nb=2", "c") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_is_stripped() -> None:
    assert config_value("  name  =  value with spaces  \n", "name") == "value with spaces"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_lines_without_equals_are_ignored() -> None:
    assert config_value("garbage\na=1\nmore garbage", "a") == "1"
    assert config_value("garbage", "garbage") == ""


def test_blank_lines_are_ignored() -> None:
    assert config_value("\n\n  \na=1\n\n", "a") == "1"


def test_comment_lines_are_ignored() -> None:
    assert config_value("# a=1\nb=2", "a") == ""
    assert config_value("  # a=1\na=3", "a") == "3"


def test_first_occurrence_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_is_case_sensitive() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("Key=1", "Key") == "1"


def test_key_must_match_whole_name() -> None:
    assert config_value("abc=1", "ab") == ""
    assert config_value("ab=1\nabc=2", "abc") == "2"


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_no_trailing_newline() -> None:
    assert config_value("a=1\nb=2", "b") == "2"
